INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$geymerlar-uchun-obunalar$x$,
  $x$Geymerlar uchun obunalar: Oʻzbekistonda nimani olish mumkin$x$,
  $x$Discord Nitro, Telegram Premium va Telegram Stars: har biri nima beradi, kimga mos va Click, Payme yoki Uzum orqali soʻmda qanday toʻlanadi.$x$,
$x$<h2>Asosiysi</h2>
<ul>
<li>Oʻzbekistonda Discord Nitro va Telegram Premium obunasini soʻmda olish, Telegram Stars sotib olish mumkin.</li>
<li>Nitro Discord ovozli kanallarida koʻp vaqt oʻtkazadigan va doʻstlariga strim qiladiganlar uchun. Premium — Telegramda yashaydiganlar uchun.</li>
<li>Stars obuna emas, balki bir martalik xaridlar uchun Telegram valyutasi.</li>
<li>Game Pass va PS Plus — boshqa turdagi, konsollar uchun obunalar. Bu doʻkonlarda Oʻzbekiston regioni yoʻq, ularni toʻgʻridan-toʻgʻri soʻmda toʻlab boʻlmaydi.</li>
</ul>
<p>Oʻzbekistondagi geymer uchun eng oson yoʻl — konsol va doʻkon regioniga bogʻlanmagan obunalar: Discord Nitro va Telegram Premium. Quyida har biri nima berishi, kimga keraki va qanday toʻlanishi haqida.</p>
<h2>Nimani olish mumkin</h2>
<p><strong>Discord Nitro.</strong> 1 GB gacha fayl yuklash, yuqori sifatli strim, ikkita server busti, animatsiyali avatar va istalgan serverda oʻz emojilaringiz. Yengil Nitro Basic ham bor: 50 MB gacha fayl, bustsiz. Nitro oyiga 9,99 dollar, Basic — 2,99 dollar (<a href="https://discord.com/nitro">Discord</a>). Tariflar haqida batafsil: <a href="/uz/blog/discord-nitro-uzbekiston">Oʻzbekistonda Discord Nitro</a>.</p>
<p><strong>Telegram Premium.</strong> 4 GB gacha fayl yuklash, tezroq yuklab olish, koʻproq kanal va papka, ovozli xabarlarni matnga aylantirish, emoji-status va premium stikerlar. Bitta obuna barcha qurilmalaringizda ishlaydi. Batafsil: <a href="/uz/blog/telegram-premium">Oʻzbekistonda Telegram Premium</a>.</p>
<p><strong>Telegram Stars.</strong> Telegram valyutasi. Ular botlar va mini-ilovalarda, sovgʻalarga va kanallarni qoʻllab-quvvatlashga sarflanadi. Bu bir martalik xarid: qancha olsangiz, shuncha sarflaysiz.</p>
<h2>Game Pass va PS Plus</h2>
<p>Game Pass va PS Plus — Xbox va PlayStation uchun oʻyinlar kutubxonasi va onlayn obunalari. Ularni Nitro va Premium bilan solishtirishning maʼnosi yoʻq: ular boshqa vazifani bajaradi.</p>
<p>Microsoft Store va PlayStation Storeʼda Oʻzbekiston regioni yoʻq, shuning uchun bunday obunani toʻgʻridan-toʻgʻri soʻmda toʻlab boʻlmaydi. Konsolingiz boʻlsa, bu masala alohida — boshqa region akkaunti va uning qoidalari orqali hal qilinadi.</p>
<h2>Qaysi birini tanlash</h2>
<ul>
<li>Kompyuterda oʻynaysiz va Discord ovozli kanallarida oʻtirasiz — Nitro oling. Bust va katta fayllar kerak boʻlmasa, Nitro Basic yetarli.</li>
<li>Telegramda yozishasiz, kanal yoki klan chatini yuritasiz — Premium oling.</li>
<li>Obuna kerak emas, lekin botga toʻlash, sovgʻa qilish yoki kanalni qoʻllab-quvvatlash kerak — Stars sotib oling.</li>
</ul>
<p>Ikkilansangiz, asosiy platformangiz uchun bitta obunadan boshlang. Ikkinchisini keyin qoʻshish mumkin.</p>
<h2>Soʻmda qanday toʻlanadi</h2>
<p>YuPayʼda har bir obunaning narxi soʻmda koʻrsatilgan. Yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi. Click, Payme yoki Uzum orqali toʻlash mumkin, xorijiy karta kerak emas.</p>
<ol>
<li>Kerakli sahifani oching: <a href="/uz/store/discord">Discord</a>, <a href="/uz/store/telegram-premium">Telegram Premium</a> yoki <a href="/uz/store/telegram-stars">Telegram Stars</a>.</li>
<li>Muddat yoki miqdorni tanlang.</li>
<li>Premium va Stars uchun Telegramdagi @username ni kiriting. Parol va SMS kod kerak emas.</li>
<li>Toʻlang.</li>
</ol>
<p>Premium va Stars akkauntga username orqali tushadi. Nitro buyurtmada va pochtaga kod sifatida keladi: uni Discord sozlamalarida, «Sovgʻalar» (Gift Inventory) boʻlimida kiritasiz.</p>
<h2>Nimaga eʼtibor berish kerak</h2>
<ul>
<li>Toʻlashdan oldin username ni tekshiring. Obuna siz kiritgan akkauntga tushadi.</li>
<li>Sovgʻa uchun olingan Nitro kodini oʻzingiz ochmang, aks holda obuna sizning profilingizga bogʻlanib qoladi.</li>
<li>Parol va SMS kodlarni hech kimga bermang. Xarid uchun ular kerak emas. Batafsil: <a href="/uz/blog/oyin-valyutasini-xavfsiz-sotib-olish">oʻyin valyutasini qanday xavfsiz sotib olish</a>.</li>
</ul>$x$,
  $x$Geymerlar uchun obunalar: Nitro, Premium, Stars soʻmda$x$,
  $x$Oʻzbekistonda Discord Nitro, Telegram Premium va Telegram Stars: har bir obuna nima beradi, kimga mos va Click, Payme yoki Uzum orqali soʻmda qanday toʻlanadi.$x$
);

